import { describe, expect, it } from 'vitest';
import { createGrid } from '../engine/grid';
import { buildSlotLookup } from './hint-lookup';
import { adjacentHintKey, hintOrder } from './hint-order';

// Story 15-S4 — the Hint Box's reading order: every Across word by number,
// then every Down word, wrapping both ways. Do not edit this file to match
// an implementation.

// 3×3 with the center black: 1 and 3 Across, 1 and 2 Down.
const ring = buildSlotLookup(createGrid({ cols: 3, rows: 3, black: [{ col: 1, row: 1 }] }));

describe('15-S4 hint order', () => {
  it('lists the Across words by number, then the Down words', () => {
    expect(hintOrder(ring)).toEqual(['1-across', '3-across', '1-down', '2-down']);
    expect(hintOrder(buildSlotLookup(createGrid({ cols: 3, rows: 3 })))).toEqual([
      '1-across',
      '4-across',
      '5-across',
      '1-down',
      '2-down',
      '3-down',
    ]);
  });

  it('steps forward and back through that order', () => {
    expect(adjacentHintKey(ring, '1-across', 1)).toBe('3-across');
    expect(adjacentHintKey(ring, '3-across', 1)).toBe('1-down');
    expect(adjacentHintKey(ring, '1-down', -1)).toBe('3-across');
  });

  it('wraps from the last Down to the first Across, and back', () => {
    expect(adjacentHintKey(ring, '2-down', 1)).toBe('1-across');
    expect(adjacentHintKey(ring, '1-across', -1)).toBe('2-down');
  });

  it('stays on the only word of a single-word grid', () => {
    const single = buildSlotLookup(createGrid({ cols: 3, rows: 1 }));
    expect(hintOrder(single)).toEqual(['1-across']);
    expect(adjacentHintKey(single, '1-across', 1)).toBe('1-across');
    expect(adjacentHintKey(single, '1-across', -1)).toBe('1-across');
  });

  it('returns null for a key that isn’t a word', () => {
    expect(adjacentHintKey(ring, '9-across', 1)).toBeNull();
    expect(adjacentHintKey(new Map(), '1-across', 1)).toBeNull();
  });
});
